import{h as d,j as e,i as p,R as m,C as h,Y as u}from"./main-wIw8MY6Z.js";import{P as y}from"./PageHero-CQtHume1.js";const g={"clinic-policy":{title:"CLINIC POLICY",intro:"Please note that by booking a Beauty Aesthetics Skincare appointment you are accepting the terms and conditions of our Clinic policy.",sections:[{heading:"FEEDBACK",body:["Any feedback regarding your treatments is greatly appreciated. You can leave feedback via our Facebook page."]},{heading:"ARRIVING AT THE CLINIC",body:["If you are new to the Clinic please arrive 10 minutes before your appointment time. This will give you plenty of time to check in and fill out the Client Consultation Form. Arriving late will rob you of precious appointment minutes as each session will be finished exactly on time as a courtesy to the next client.","We fully understand that sometimes being late is outside of your control. If you are running late, please contact the Clinic as soon as possible by phone to allow your therapist to advise the best course of action.","We will always do our best to accommodate late arrivals (within 10 minutes after your appointment) by performing the most complete treatment possible in the time remaining.","Unfortunately, arriving 10 minutes after the scheduled time of your appointment may result in the cancellation of your appointment, our cancellation policy will apply.","We recommend that you plan ahead for your visit to our Clinic.","We’ll be happy to answer any questions you may have about our location, parking, and travel options."]},{heading:"BOOKING APPOINTMENTS VIA PHONE OR SOCIAL MEDIA",body:["The preferred method of booking an appointment is online via our website, where the availability of each treatment can be found and your deposit can be paid to secure your booking. Bookings can also be made via our social media sites. Please note, booking an appointment via social media, the appointment will not be booked until the appointment time has been confirmed to the client by the Clinic and the deposit received. Being offered a time slot does not guarantee the space until the clinic has confirmed it with the client.","We regret we cannot hold bookings with Facebook appointments until confirmation. Luna Moon Aesthetics runs on an appointment-based system and these go on a first-come-first-serve basis. We do not hold back any appointments for last minute calls, so we always advise you to book in advance to avoid disappointment. Remember that during the summer months and at Christmas time we do get extremely busy and appointments can go 2-3 weeks in advance (sometimes longer for late nights and weekends).","SYMPTOMS OF COVID-19: If you are experiencing any symptoms of Covid 19 which include high fever, continuous cough, loss of sense of smell and taste, please reschedule your appointment."]},{heading:"CANCELLATIONS",body:["Please understand that as a Clinic we run on an appointment basis. When a client cancels late or misses appointments this costs the Clinic financially. We do appreciate that things do crop up, so we do ask you to notify the Clinic as soon as possible. If you miss an appointment, we will contact you to notify you on the missed appointment. If you find it difficult to remember appointments then we do offer a text to remind service. But please note that it is still your responsibility to remember the appointment. If you have missed several appointments, we recommend that you ring the Clinic on the day that you wish to have the appointment, and we will do our best to fit you in. We do appreciate your custom, and also appreciate our time is precious."]},{heading:"CANCELLATION POLICY",body:["If you need to cancel your appointment, please call the Clinic at least 24 hours (48 duo and packages) in advance. We will work with you to re-schedule your appointment, but please note this could be several days later. Deposits will not be refunded for cancellations but appointments can be re-scheduled without incurring further costs."]}]}};function x({slug:i,fallbackTitle:l}){var s;const{data:o,loading:c}=d(()=>u(i),[i]),t=(s=o==null?void 0:o.content)!=null&&s.trim()?o:null,n=g[i];return e.jsxs(e.Fragment,{children:[e.jsx(y,{title:(t==null?void 0:t.title)??(n==null?void 0:n.title)??l,image:window.__LUNAMOON_DIST__+"images/clinic-reception.jpg"}),e.jsx("section",{className:"section-padding",children:e.jsx("div",{className:"container-prose",children:c?e.jsx(p,{}):t?e.jsxs(e.Fragment,{children:[e.jsx(m,{html:t.content}),t.updated&&e.jsxs("p",{className:"mt-10 border-t border-ink-100 pt-6 text-sm text-ink-400",children:["Last updated"," ",new Date(t.updated).toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric"})]})]}):n?e.jsxs(e.Fragment,{children:[e.jsx("p",{className:"text-lg leading-relaxed text-ink-700",children:n.intro}),e.jsx("div",{className:"mt-10 space-y-10",children:n.sections.map(a=>e.jsxs("section",{children:[e.jsx("h2",{className:"font-display text-xl uppercase tracking-wide text-ink-900 sm:text-2xl",children:a.heading}),e.jsx("div",{className:"mt-4 space-y-4 leading-relaxed text-ink-600",children:a.body.map(r=>e.jsx("p",{children:r},r))})]},a.heading))})]}):e.jsx("div",{className:"rounded-2xl bg-ink-50 p-8 text-center",children:e.jsxs("p",{className:"text-ink-600",children:["This page hasn’t been added yet. Create a page with the slug"," ",e.jsx("code",{className:"rounded bg-white px-1.5 py-0.5 text-sm",children:i})," in wp-admin and its content will appear here."]})})})}),e.jsx(h,{})]})}export{x as default};
